var inner;

try {
    inner = typeof msg.rawData === "string"
        ? JSON.parse(msg.rawData)
        : msg.rawData;
} catch (e) {
    return [];
}

var outputMessages = [];


var LECTURA_INICIAL = parseInt(metadata.ss_consumo_inicial);

function timestamp(t) {
    var a = String(t || "").match(/\d+/g);

    if (!a || a.length < 6) {
        return null;
    }

    return new Date(
        Number(a[0]),
        Number(a[1]) - 1,
        Number(a[2]),
        Number(a[3]),
        Number(a[4]),
        Number(a[5])
    ).getTime();
}

function signed32(value) {
    return value >= 0x80000000
        ? value - 0x100000000
        : value;
}

function decode(payload) {
    if (typeof payload !== "string") {
        return null;
    }

    payload = payload.replace(/\s/g, "");

    /*
     * 57 bytes:
     * 1 byte PAYVER + 56 bytes de datos.
     */
    if (!/^[0-9a-f]{114}$/i.test(payload)) {
        return null;
    }

    var payver = parseInt(payload.substr(0, 2), 16);

    if (payver !== 1) {
        return null;
    }

    var v = [];

    
    for (var i = 0; i < 14; i++) {
        var p = 2 + i * 8;

        var reordered =
            payload.substr(p + 4, 4) +
            payload.substr(p, 4);

        v[i] = parseInt(reordered, 16);
    }

    var pfRaw = signed32(v[13]);

    return {
        payver: payver,

        energia_importada_L1_raw: v[0],
        energia_importada_L2_raw: v[1],
        energia_importada_L3_raw: v[2],

        energia_importada_total_raw: v[3],
        energia_importada_total_suma:
            v[3] + LECTURA_INICIAL,

        tension_L1_V: v[4],
        tension_L2_V: v[5],
        tension_L3_V: v[6],

        corriente_L1_raw: v[7],
        corriente_L2_raw: v[8],
        corriente_L3_raw: v[9],

        potencia_activa_total_raw: signed32(v[10]),
        potencia_reactiva_total_raw: signed32(v[11]),
        potencia_aparente_total_raw: v[12],

        factor_potencia_total_raw: pfRaw,
        factor_potencia_total: pfRaw / 1000
    };
}

function add(payload, time, actual) {
    var values = decode(payload);

    if (!values) {
        return;
    }

    var ts = timestamp(time);

    if (ts === null) {
        return;
    }

    if (actual) {
        values.battery = inner.battery;
        values.signal = inner.signal;
    }

    outputMessages.push({
        msg: {
            ts: ts,
            values: values
        },
        metadata: metadata,
        msgType: msgType
    });
}

// Lectura actual
add(inner.Payload, inner.time, true);

// Lecturas históricas
var historicalKeys = [];

for (var key in inner) {
    if (
        Object.prototype.hasOwnProperty.call(inner, key) &&
        /^\d+$/.test(key) &&
        Array.isArray(inner[key])
    ) {
        historicalKeys.push(Number(key));
    }
}

historicalKeys.sort(function (a, b) {
    return a - b;
});

for (var j = 0; j < historicalKeys.length; j++) {
    var historical = inner[String(historicalKeys[j])];

    if (historical.length >= 2) {
        add(historical[0], historical[1], false);
    }
}

return outputMessages;
